<?php
require_once __DIR__ . '/../core/db.php'; require_once __DIR__ . '/../core/functions.php'; require_once __DIR__ . '/../core/security.php'; require_once __DIR__ . '/../core/auth.php'; require_once __DIR__ . '/../core/rbac.php'; require_once __DIR__ . '/../core/branch_portal.php';
$branchId=require_portal_branch_id(); $branch=portal_branch_row($branchId); $customCss=setting('custom_css','');
$stmt=db()->prepare("SELECT ps.*, ou.name opened_name, cu.name closed_name FROM pos_shifts ps LEFT JOIN users ou ON ou.id=ps.opened_by LEFT JOIN users cu ON cu.id=ps.closed_by WHERE ps.branch_id=? ORDER BY ps.opened_at DESC LIMIT 200"); $stmt->execute([$branchId]); $rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
function navc($a){$items=['index.php'=>'Dashboard','sales.php'=>'Penjualan','shifts.php'=>'Shift','stock.php'=>'Stok']; echo '<div class="card" style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px">'; foreach($items as $u=>$l){echo '<a class="'.e($a===$u?'btn':'btn secondary').'" href="'.e(base_url('cabang/'.$u)).'">'.e($l).'</a>'; } echo '</div>';}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shift Cabang</title><link rel="stylesheet" href="<?php echo e(asset_url('assets/app.css')); ?>"><style><?php echo $customCss; ?></style></head><body><div class="main" style="margin:0"><div class="content"><h2>Laporan Shift: <?php echo e($branch['branch_name'] ?? ''); ?></h2><?php navc('shifts.php'); ?><div class="card"><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Status</th><th>Buka</th><th>Tutup</th><th>Kas Awal</th><th>Kas Aktual</th><th>Selisih</th><th>Kasir</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?php echo e($r['shift_code']); ?></td><td><?php echo e($r['status']); ?></td><td><?php echo e($r['opened_at']); ?></td><td><?php echo e($r['closed_at'] ?? '-'); ?></td><td>Rp <?php echo e(format_money($r['opening_cash_actual'])); ?></td><td>Rp <?php echo e(format_money($r['counted_cash_total'] ?? 0)); ?></td><td>Rp <?php echo e(format_money($r['cash_difference'] ?? 0)); ?></td><td><?php echo e($r['opened_name'] ?? '-'); ?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="8">Belum ada shift.</td></tr><?php endif; ?></tbody></table></div></div></div></div></body></html>
